import { SCORED_AXES } from '../scoring.js';
import type { AuditReport, AxisScore, Finding } from '../types.js';

/**
 * Deterministic Markdown rendering of an AuditReport.
 *
 * Template follows the `site-audit` skill output-template (8 axes, P0-P3,
 * matrice ROI, quick wins, conclusion). Used as:
 *   - Email body (Resend), text-only audience.
 *   - Fallback rendering when the Next.js HTML page is offline.
 *   - Snapshot stored alongside the audit for archival.
 *
 * Visual styling stays in apps/web/app/audit/[slug]/page.tsx — the PDF is
 * generated by Puppeteer hitting that same Next.js page. This file does
 * NOT define any visual style; it's plain Markdown.
 */

const AXIS_LABEL: Record<AxisScore['axis'], string> = {
  ux: 'UX',
  ui: 'UI',
  seo_technique: 'SEO Technique',
  seo_contenu: 'SEO Contenu & Stratégie mots-clés',
  performance: 'Performance',
  accessibilite: 'Accessibilité',
  conformite: 'Conformité légale',
  conversion: 'Conversion',
};

const SEVERITY_BADGE: Record<Finding['severity'], string> = {
  P0: '🔴 P0',
  P1: '🟠 P1',
  P2: '🟡 P2',
  P3: '🟢 P3',
};

const EFFORT_LABEL: Record<NonNullable<Finding['effortDefault']>, string> = {
  quick_win: 'Quick win < 2h',
  standard: 'Standard 1-2j',
  important: 'Important 1+ semaine',
};

export function renderMarkdownReport(report: AuditReport): string {
  const lines: string[] = [];
  const date = formatDate(report.scannedAt);
  const host = safeHost(report.url);

  lines.push(`# Audit complet — ${host}`);
  lines.push('');
  lines.push(`**URL auditée** : ${report.url}`);
  lines.push(`**Date** : ${date}`);
  lines.push(`**Secteur identifié** : ${capitalize(report.sector.detected)}`);
  lines.push(`**KPI principal** : ${report.sector.mainKpi}`);
  if (report.sector.secondaryKpi) {
    lines.push(`**KPI secondaire** : ${report.sector.secondaryKpi}`);
  }
  lines.push('');
  lines.push('---');
  lines.push('');

  lines.push('## 📋 Résumé exécutif');
  lines.push('');
  lines.push(report.execSummary || '_Synthèse en cours de génération._');
  lines.push('');
  lines.push(
    report.globalScore === null
      ? '**Score global estimé** : Non évalué'
      : `**Score global estimé** : ${Math.round(report.globalScore * 10).toString()}/100 (${capitalize(report.globalBand ?? '')})`,
  );
  lines.push('');
  if (report.top3Priorities.length > 0) {
    lines.push('**Top 3 priorités** :');
    report.top3Priorities.forEach((p, i) => {
      lines.push(`${(i + 1).toString()}. ${p.title}`);
    });
    lines.push('');
  }
  if (report.estimatedImpactNarrative) {
    lines.push(`**Potentiel d'amélioration** : ${report.estimatedImpactNarrative}`);
    lines.push('');
  }
  lines.push('---');
  lines.push('');

  // Critical findings detail
  const criticals = report.findings.filter((f) => f.severity === 'P0');
  if (criticals.length > 0) {
    lines.push('## 🎯 Points critiques détaillés');
    lines.push('');
    for (const f of criticals) {
      lines.push(`### ${SEVERITY_BADGE[f.severity]} — ${f.title}`);
      lines.push('');
      lines.push('**Constat** :');
      lines.push('');
      lines.push(f.narrative?.constat ?? formatEvidence(f));
      lines.push('');
      if (f.narrative?.impactBusiness) {
        lines.push('**Impact business** :');
        lines.push('');
        lines.push(f.narrative.impactBusiness);
        lines.push('');
      }
      lines.push('**Recommandation** :');
      lines.push('');
      lines.push(f.narrative?.recommandation ?? 'À détailler.');
      lines.push('');
      if (f.narrative?.codeSnippet) {
        lines.push('```');
        lines.push(f.narrative.codeSnippet);
        lines.push('```');
        lines.push('');
      }
      lines.push(`**Effort estimé** : ${EFFORT_LABEL[f.effortDefault]}`);
      if (f.legalRefs.length > 0) {
        lines.push('');
        lines.push(
          `**Références** : ${f.legalRefs
            .map((r) => (r.url ? `[${r.label}](${r.url})` : r.label))
            .join(', ')}`,
        );
      }
      lines.push('');
      lines.push('---');
      lines.push('');
    }
  }

  // Per-axis detail
  lines.push('## 📊 Audit par axe');
  lines.push('');
  for (const axis of SCORED_AXES) {
    const score = report.scores.find((s) => s.axis === axis);
    if (!score) {
      lines.push(`### ${AXIS_LABEL[axis]} - Non évalué`, '');
      for (const finding of report.findings.filter((f) => f.axis === axis)) {
        lines.push(`- ${finding.title}`);
      }
      lines.push('');
      continue;
    }
    const axisFindings = report.findings.filter((f) => f.axis === score.axis);
    lines.push(
      `### ${AXIS_LABEL[score.axis]} — Score : ${Math.round(score.score * 10).toString()}/100 (${capitalize(score.band)})`,
    );
    lines.push('');
    if (axisFindings.length === 0) {
      lines.push("_Aucun point d'amélioration détecté sur cet axe._");
      lines.push('');
      continue;
    }
    for (const f of axisFindings) {
      const narrative = f.narrative;
      const constat = narrative ? (narrative.constat.split('\n')[0] ?? '') : formatEvidenceShort(f);
      const reco = narrative ? (narrative.recommandation.split('\n')[0] ?? '') : '';
      lines.push(
        `- **${SEVERITY_BADGE[f.severity]} ${f.title}** — ${constat}${reco ? ` → ${reco}` : ''}`,
      );
    }
    lines.push('');
  }

  // ROI matrix
  lines.push('## 🚀 Matrice de priorisation ROI');
  lines.push('');
  lines.push('| Priorité | Action | Effort |');
  lines.push('|----------|--------|--------|');
  const sorted = [...report.findings].sort(
    (a, b) => severityRank(a.severity) - severityRank(b.severity),
  );
  for (const f of sorted.slice(0, 20)) {
    lines.push(`| ${f.severity} | ${escapeTable(f.title)} | ${EFFORT_LABEL[f.effortDefault]} |`);
  }
  lines.push('');

  // Quick wins
  if (report.quickWins.length > 0) {
    lines.push('## ⚡ Quick wins (< 1 semaine, impact immédiat)');
    lines.push('');
    report.quickWins.forEach((q, i) => {
      lines.push(`${(i + 1).toString()}. ${q}`);
    });
    lines.push('');
  }

  // Killer findings
  if (report.killerFindings.length > 0) {
    lines.push('## 🔥 Findings majeurs identifiés');
    lines.push('');
    for (const id of report.killerFindings) {
      const f = report.findings.find((x) => x.id === id);
      if (f) lines.push(`- **${f.title}**`);
    }
    lines.push('');
  }

  // Stack info
  lines.push('## 🔧 Stack détecté');
  lines.push('');
  lines.push(
    `- Technologie : **${report.facts.stack.stack}** (confiance ${(report.facts.stack.confidence * 100).toFixed(0)}%)`,
  );
  if (report.facts.sitemap.found && report.facts.sitemap.foundAt) {
    lines.push(
      `- Sitemap : ${report.facts.sitemap.foundAt} (${report.facts.sitemap.urlsCount.toString()} URLs)`,
    );
  } else {
    lines.push('- Sitemap : introuvable');
  }
  lines.push('');

  lines.push('---');
  lines.push('');
  lines.push(
    `*Audit réalisé le ${date}. Estimations indicatives, à corréler avec vos données analytics.*`,
  );
  lines.push('');

  return lines.join('\n');
}

function formatEvidence(f: Finding): string {
  if (Object.keys(f.evidence).length === 0) return f.title;
  return `${f.title}. Détails : \`${JSON.stringify(f.evidence).slice(0, 200)}\``;
}

function formatEvidenceShort(f: Finding): string {
  const keys = Object.keys(f.evidence);
  if (keys.length === 0) return '';
  const first = keys[0];
  if (!first) return '';
  const v = f.evidence[first];
  const str =
    typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean'
      ? String(v)
      : Array.isArray(v)
        ? `${v.length.toString()} entrée(s)`
        : JSON.stringify(v).slice(0, 80);
  return `${first}: ${str.slice(0, 100)}`;
}

function severityRank(s: Finding['severity']): number {
  return { P0: 0, P1: 1, P2: 2, P3: 3 }[s];
}

function capitalize(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function safeHost(url: string): string {
  try {
    return new URL(url).host;
  } catch {
    return url;
  }
}

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleDateString('fr-FR', {
      day: 'numeric',
      month: 'long',
      year: 'numeric',
    });
  } catch {
    return iso;
  }
}

function escapeTable(s: string): string {
  return s.replace(/\|/g, '\\|').replace(/\n/g, ' ');
}
